def solution(operations):
    s1 = []
    s2 = []
    res = []
    for op in operations:
        cmd = op[0]
        if cmd == 'push':
            val = op[1]
            s1.append(val)
        elif cmd == 'pop':
            if not s2:
                while s1:
                    s2.append(s1.pop())
            if s2:
                res.append(s2.pop())
    return res
